<script setup lang="ts">
import { ref } from 'vue'; import { api } from '../api/client'; import { useSession } from '../composables/session'
const session=useSession();const username=ref('');const password=ref('');const bind=ref<any>();const saved=ref('');const error=ref('')
async function register(){try{await api('/auth/register',{method:'POST',body:JSON.stringify({username:username.value,password:password.value})});await session.load();saved.value='账号已设置'}catch(e){error.value=e instanceof Error?e.message:'设置失败'}}
async function bot(){bind.value=await api('/me/bot-bind-token',{method:'POST'})}
</script>
<template><section class="shell page"><div class="page-head"><div><p class="eyebrow">个人设置</p><h1>{{session.user.value?.display_name||'登录或创建身份'}}</h1></div></div><div v-if="session.user.value" class="grid"><article v-if="!session.user.value.username" class="card stack"><h2>把访客升级为账号</h2><p class="muted">升级后用户 ID 不变，已有课表、活动和账款都会保留。</p><label>用户名<input v-model="username" autocomplete="username"></label><label>密码<input v-model="password" type="password" autocomplete="new-password" minlength="10"></label><button class="primary" @click="register">设置账号</button></article><article class="card stack"><h2>绑定 AstrBot</h2><p class="muted">生成 10 分钟有效的一次性绑定码，然后私聊 Bot。</p><button @click="bot">生成绑定码</button><div v-if="bind" class="bind"><strong>{{bind.code}}</strong><p>/羽球 绑定 {{bind.code}}</p></div></article></div><article v-else class="card empty"><p>请从首页创建活动，或通过邀请链接加入。</p><RouterLink class="button primary" to="/">回到首页</RouterLink></article><p v-if="saved">{{saved}}</p><p v-if="error" class="error">{{error}}</p></section></template>
<style scoped>.bind{padding:16px;background:var(--primary-soft);border-radius:12px}.bind strong{font-size:24px;letter-spacing:.12em}.bind p{margin:8px 0 0}</style>
